// Checked-in production-shaped agent-loop fixture for the empty-stream recovery
// regression. The bytes below mirror the installed dsh-agent-loop step()
// structure (same anchor lines, same settlement, same waterfall payload shape)
// so the injector applies to it exactly as it does to the real module. The
// compact stream records reproduce dsh-llm's AssistantStreamAccumulator
// snapshot shapes: merged text-chunks/reasoning-chunks/tool-call-chunks
// records for deltas and bare chunk records for usage/finish/block markers.
// Tests that need the real installed runtime stay conditional in the spec;
// this fixture keeps the portable regression meaningful without any runtime.
export const fixtureAgentLoopSource = [
	'class LlmError extends Error {',
	'	constructor(message, code, failure) {',
	'		super(message);',
	'		this.code = code;',
	'		this.failure = failure;',
	'	}',
	'}',
	'class StreamAttempt {',
	'	records = [];',
	'	terminal = false;',
	'	replayState;',
	'	finishReason;',
	'	push(chunk) {',
	'		if (chunk.type === "text-delta" || chunk.type === "reasoning-delta") this.records.push({ type: chunk.type === "text-delta" ? "text-chunks" : "reasoning-chunks", index: chunk.index, texts: [chunk.text] });',
	'		else if (chunk.type === "tool-call-delta") this.records.push({ type: "tool-call-chunks", index: chunk.index });',
	'		else {',
	'			this.records.push({ type: "chunk", time: 0, chunk });',
	'			if (chunk.type === "finish") {',
	'					this.finishReason = chunk.reason;',
	'					this.replayState = chunk.replayState;',
	'				}',
	'		}',
	'	}',
	'	get ended() { return this.terminal; }',
	'	get stream() { return this.records; }',
	'	get finish() { return this.finishReason ?? { kind: "stop" }; }',
	'	blocks() {',
	'		return this.records.filter(record => record.type === "text-chunks").map(record => ({ type: "text", text: record.texts.join("") }));',
	'	}',
	'	settle(eventType, append) { append(); this.terminal = true; }',
	'	abandon() { this.terminal = true; }',
	'	interruptedBlocks() { return []; }',
	'}',
	'class AgentLoopProbe {',
	'	async step(decision) {',
	'		const { turn, step, abort: { signal } } = this.phase;',
	'		signal.throwIfAborted();',
	'		let firstAttempt = true;',
	'		while (true) {',
	'			const { config, preparedCall } = await this.prepareRequest(turn, step, signal);',
	'			signal.throwIfAborted();',
	'			firstAttempt = false;',
	'			const request = this.buildRequest(config);',
	'			const live = new StreamAttempt();',
	'			let started = false;',
	'			try {',
	'				const stream = preparedCall?.stream(request) ?? this.loopCtx.llm.stream(request);',
	'				signal.throwIfAborted();',
	'				started = true;',
	'				for await (const chunk of stream) {',
	'					signal.throwIfAborted();',
	'					live.push(chunk);',
	'				}',
	'				signal.throwIfAborted();',
	'			} catch (error) {',
	'				if (!started) throw error;',
	'				try {',
	'					live.settle("assistant/attempt", () => this.session.append("assistant/attempt", {',
	'						turn,',
	'						step,',
	'						stream: live.stream',
	'					}).seq);',
	'				} catch (settlementError) {',
	'					throw new AggregateError([error, settlementError], "Assistant stream failed and its durable settlement was rejected", { cause: error });',
	'				}',
	'				throw error;',
	'			}',
	'			try {',
	'				const finish = live.finish;',
	'				if (finish.kind === "error" || finish.kind === "aborted") {',
	'					live.settle("assistant/attempt", () => this.session.append("assistant/attempt", {',
	'						turn,',
	'						step,',
	'						stream: live.stream',
	'					}).seq);',
	'					const action = await this.dispatch.waterfall("agent/request-error", {',
	'						turn,',
	'						step,',
	'						provider: request.provider,',
	'						failure: finish.failure,',
	'						retryPolicy: preparedCall?.retryPolicy,',
	'						signal',
	'					}, () => Promise.resolve(void 0));',
	'					signal.throwIfAborted();',
	'					if (action?.kind !== "retry") throw new LlmError(finish.failure.message, finish.failure.code, finish.failure);',
	'					continue;',
	'				}',
	'				const message = createAssistantMessage({ content: live.blocks(), source: { provider: request.provider, model: request.model } });',
	'				live.settle("assistant/message", () => this.session.append("assistant/message", {',
	'					turn,',
	'						step,',
	'						message',
	'				}).seq);',
	'				return { kind: "completed" };',
	'			} catch (error) {',
	'				if (!live.ended) live.abandon();',
	'				throw error;',
	'			}',
	'		}',
	'	}',
	'}',
].join('\n')
